// Read-only, fixture-specific measurements after visual inspection of r6 outputs.
// Never modifies generated files; fixed coordinates are documented observations.
import {createRequire} from 'node:module';import {readFile,writeFile} from 'node:fs/promises';import path from 'node:path';
const require=createRequire(new URL('../../apps/paperbanana-api/package.json',import.meta.url)),sharp=require('sharp'),dir=process.argv[2];
const specs=[{file:'generate-png-1-candidate-0.png',zero:617,alphaX:570,betaX:790,scanFrom:430,flowX:300,flowFrom:150,flowTo:340},{file:'refine-png-1-candidate-0.png',zero:1326,alphaX:1140,betaX:1570,scanFrom:880,flowX:600,flowFrom:300,flowTo:650},{file:'restored-png-1-candidate-0.png',zero:680,max40:392,alphaX:500,betaX:900,scanFrom:395,flowX:300,flowFrom:55,flowTo:220}];
const results=[];for(const s of specs){const {data,info}=await sharp(await readFile(path.join(dir,s.file))).flatten({background:'#fff'}).removeAlpha().raw().toBuffer({resolveWithObject:true});const blue=(x,y)=>{const i=(y*info.width+x)*info.channels,[r,g,b]=data.subarray(i,i+3);return b-r>30&&b>120&&r<150};const first=(x,start,end)=>{for(let y=start;y<end;y++)if(Array.from({length:6},(_,i)=>blue(x,y+i)).every(Boolean))return y;throw Error('No contiguous bar pixels at expected position');};const alphaTop=first(s.alphaX,s.scanFrom,s.zero),betaTop=first(s.betaX,s.scanFrom,s.zero),flowTop=first(s.flowX,s.flowFrom,s.flowTo);const alphaHeight=s.zero-alphaTop,betaHeight=s.zero-betaTop;results.push({...s,width:info.width,height:info.height,alphaTop,betaTop,alphaHeight,betaHeight,flowTop,normalizedFlowTop:flowTop/info.height,...(s.max40?{encodedAlpha:alphaHeight/(s.zero-s.max40)*40,encodedBeta:betaHeight/(s.zero-s.max40)*40}:{}),heightRatio:alphaHeight/betaHeight,expectedRatio:35/12,relativeRatioError:Math.abs(alphaHeight/betaHeight/(35/12)-1),axisLabelInspection:s.file.startsWith('restored')?'Axis has 0 at y=680, 40 at y=392; labels are present, but bar geometry encodes different values.':s.file.startsWith('generate')?'Only 0 is labeled; bar ratio still independently checkable.':'0,10,20,30,40 are visible. Review incorrectly says only 0 exists, despite receiving this image first.',method:'Manually verified interior sampling positions; six contiguous blue pixels identify top boundaries; 2px/4px approximate boundary tolerance. Ratio is independent of the ambiguous axis. No image edited; not a general chart parser or statistical certificate.'});}
await writeFile(path.join(dir,'independent-png-measurements.json'),JSON.stringify(results,null,2));console.log(JSON.stringify(results,null,2));
